/**
 * A linha do tempo da criação — porte de `componentes/viz/terra_criacao.js`.
 *
 * A Terra atravessando os oito estágios de Gênesis 1, conforme o investigador
 * monta a linha do tempo. Do escuro sob um manto de vapor à luz difusa; a
 * expansão que separa as águas; a terra firme que emerge e reverdece; o Sol que
 * — já existindo desde o princípio — só fica VISÍVEL da superfície no 4º dia,
 * quando o céu clareia; e a vida enchendo mares, céus e, por fim, a terra.
 *
 * A cena não julga nada: ela encena o estágio do último card colocado
 * (`info.terra`, montado em `estagios.ts`). Quem corrige é o renderizador.
 *
 * Sobre a Terra ter deixado de ser uma esfera de Three.js, ver `globo.ts`.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  etiqueta,
  infoDe,
  limitar,
  paleta,
  texto,
  textoDe,
  titulo,
} from './desenho.ts';
import { CONTINENTES, globo, NUVENS } from './globo.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** O que um estágio diz sobre como a Terra estava. */
interface Terra {
  readonly luz: number;
  readonly nuvens: number;
  readonly terraFirme: boolean;
  readonly verde: boolean;
  readonly sol: boolean;
  readonly vida: number;
  readonly humanos: boolean;
}

const INICIAL: Terra = {
  luz: 0.15,
  nuvens: 0.35,
  terraFirme: false,
  verde: false,
  sol: false,
  vida: 0,
  humanos: false,
};

const terraCriacao: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /** Uma ave: o traço de duas asas abertas. */
  function ave(ctx: CanvasRenderingContext2D, x: number, y: number, tamanho: number): void {
    ctx.beginPath();
    ctx.moveTo(x - tamanho, y);
    ctx.quadraticCurveTo(x - tamanho / 2, y - tamanho * 0.7, x, y);
    ctx.quadraticCurveTo(x + tamanho / 2, y - tamanho * 0.7, x + tamanho, y);
    ctx.stroke();
  }

  function peixe(ctx: CanvasRenderingContext2D, x: number, y: number, tamanho: number): void {
    ctx.beginPath();
    ctx.ellipse(x, y, tamanho, tamanho * 0.55, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(x + tamanho, y);
    ctx.lineTo(x + tamanho * 1.7, y - tamanho * 0.55);
    ctx.lineTo(x + tamanho * 1.7, y + tamanho * 0.55);
    ctx.closePath();
    ctx.fill();
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);

    const bruto = info.terra;
    const T: Terra =
      bruto !== null && typeof bruto === 'object' ? { ...INICIAL, ...(bruto as Terra) } : INICIAL;

    const rotulo = textoDe(info, 'rotulo');
    const verso = textoDe(info, 'verso');

    titulo(ctx, L, A, rotulo === '' ? 'A Terra no princípio' : rotulo);

    const cx = L * 0.5;
    const cy = A * 0.55;
    const R = Math.min(L * 0.3, A * 0.3);

    // O Sol: existe desde o princípio, mas só se vê quando o céu abre.
    const visibilidade = T.sol ? Math.max(0, 1 - T.nuvens * 1.5) : 0;
    if (visibilidade > 0.01) {
      const sx = L * 0.86;
      const sy = A * 0.24;
      const raio = R * 0.6;
      const brilho = ctx.createRadialGradient(sx, sy, raio * 0.1, sx, sy, raio);
      brilho.addColorStop(0, `rgb(255 246 210 / ${visibilidade * 100}%)`);
      brilho.addColorStop(0.35, `rgb(255 210 110 / ${visibilidade * 80}%)`);
      brilho.addColorStop(1, 'rgb(255 190 90 / 0%)');
      ctx.fillStyle = brilho;
      ctx.beginPath();
      ctx.arc(sx, sy, raio, 0, Math.PI * 2);
      ctx.fill();
    }

    // A Terra. Sem terra firme, o globo é só oceano; sem vegetação, o verde dos
    // continentes cede a um tom terroso.
    const manchas = T.terraFirme
      ? T.verde
        ? CONTINENTES
        : CONTINENTES.map((m) => ({
            ...m,
            cor: m.cor === '#2fa84e' ? '#8a7a52' : m.cor === '#1e7c39' ? '#6e6140' : m.cor,
          }))
      : [];

    globo(ctx, cx, cy, R, {
      giro: t * 10,
      manchas,
      calotas: T.terraFirme,
      atmosfera: true,
      luz: T.luz,
    });

    // O manto de vapor por cima, com giro próprio — é ele que abre ao longo dos dias.
    if (T.nuvens > 0.02) {
      globo(ctx, cx, cy, R * 1.02, {
        giro: t * 6,
        oceano: ['rgb(0 0 0 / 0%)', 'rgb(0 0 0 / 0%)'],
        manchas: NUVENS,
        opacidade: T.nuvens,
        luz: T.luz,
      });
    }

    // A vida do 5º dia: aves em volta, peixes rentes à superfície.
    if (T.vida > 0) {
      ctx.strokeStyle = cor.texto;
      ctx.lineWidth = 2;
      ctx.lineCap = 'round';
      for (let i = 0; i < 5; i++) {
        const a = t * 0.5 + i * 1.3;
        ave(ctx, cx + Math.cos(a) * R * 1.4, cy - R * 0.6 + Math.sin(t + i) * R * 0.22, R * 0.1);
      }

      ctx.fillStyle = cor.azulClaro;
      for (let i = 0; i < 5; i++) {
        const a = -t * 0.6 + i * 1.25;
        peixe(
          ctx,
          cx + Math.cos(a) * R * 1.12,
          cy + R * 0.3 + Math.sin(t * 0.8 + i) * R * 0.3,
          R * 0.07,
        );
      }
    }

    // O 6º dia. Um rótulo, e não uma figura: o casal não é o que se olha aqui.
    if (T.humanos) {
      etiqueta(
        ctx,
        'o primeiro casal humano',
        cx,
        cy - R * 1.42,
        limitar(A * 0.038, 9, 13),
        cor.ouro,
      );
    }

    if (verso !== '') {
      texto(ctx, verso, L / 2, A * 0.95, limitar(A * 0.042, 9, 13), { cor: cor.fraco, peso: 700 });
    }
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default terraCriacao;
